<section class="admin-content"><div class="admin-heading"><div><div class="eyebrow">مرکز کنترل پلتفرم</div><h1><?= e($title) ?></h1><p class="muted"><?= e($description) ?></p></div><a class="button" href="<?= url('/admin') ?>">بازگشت به داشبورد</a></div><?php if(in_array($table,['skills','categories'],true)): ?><div class="admin-panel"><h2>افزودن / ویرایش <?= $table==='skills'?'مهارت':'دسته‌بندی' ?></h2><form class="banner-admin-form" method="post" action="<?=url('/admin/catalog/save')?>"><?=csrf_field()?><input type="hidden" name="table" value="<?=e($table)?>"><input name="name" required placeholder="نام"><input name="slug" required placeholder="slug"><input name="description" placeholder="توضیحات"><input name="icon" placeholder="آیکون"><input type="number" name="category_id" placeholder="شناسه دسته‌بندی اختیاری"><button class="button">ذخیره</button></form></div><?php endif; ?><div class="admin-panel"><form class="admin-search" method="get"><input name="q" value="<?=e($search??'')?>" placeholder="جستجو در این بخش..."><button class="button button-small">جستجو</button><?php if(!empty($search)):?><a class="text-link" href="<?=url('/admin/'.$table)?>">پاک کردن</a><?php endif;?></form><div class="filter-links"><a href="<?= url('/admin/'.$table) ?>">همه</a><a href="<?= url('/admin/'.$table.'?page=1') ?>">آخرین موارد</a></div><div class="table-wrap"><table><thead><tr><?php foreach ($columns as $column): ?><th><?= e(ucwords(str_replace('_',' ', $column))) ?></th><?php endforeach; ?><th>عملیات</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><?php foreach ($columns as $column): ?><td><?= e((string)($row[$column] ?? '—')) ?></td><?php endforeach; ?><td><?php if(in_array($table,['jobs','posts','reports'],true)): ?><form method="post" action="<?=url('/admin/resource/delete')?>" onsubmit="return confirm('حذف این مورد قطعی است؟')"><?=csrf_field()?><input type="hidden" name="table" value="<?=e($table)?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><button class="action-button suspend" type="submit">حذف</button></form><?php endif;?><?php if(in_array($table,['skills','categories'],true)): ?><form method="post" action="<?=url('/admin/catalog/delete')?>"><?=csrf_field()?><input type="hidden" name="table" value="<?=e($table)?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><button class="action-button suspend" type="submit">حذف</button></form><?php endif;?><?php if($table==='reports'): ?><form method="post" action="<?=url('/admin/reports/status')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><input name="resolution" placeholder="نتیجه بررسی"><select name="status"><option value="reviewing">در بررسی</option><option value="resolved">حل‌شده</option><option value="dismissed">ردشده</option></select><button class="action-button" type="submit">ثبت</button></form><?php endif;?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td class="empty" colspan="<?= count($columns) ?: 1 ?>">رکوردی برای نمایش وجود ندارد.</td></tr><?php endif; ?></tbody></table></div><?php if(($pages??1)>1):?><div class="pagination"><?php for($i=1;$i<=($pages??1);$i++):?><a class="<?=($i===($page??1)?'active':'')?>" href="<?=url('/admin/'.$table.'?page='.$i.'&q='.rawurlencode($search??''))?>"><?=$i?></a><?php endfor;?></div><?php endif;?></div></section>